package com.example.qldetai.feature.evaluation;
import com.example.qldetai.aspect.BusinessAudit; import com.example.qldetai.exception.*; import com.example.qldetai.feature.academic.*; import com.example.qldetai.feature.communication.NotificationService; import com.example.qldetai.feature.groupregistration.GroupMemberRepository; import com.example.qldetai.feature.identity.*; import com.example.qldetai.feature.project.*; import com.example.qldetai.feature.topic.TopicSupervisorRepository; import com.example.qldetai.feature.evaluation.EvaluationAdminDtos.*; import java.math.*; import java.time.*; import java.util.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class EvaluationAdministrationService {
 private final EvaluationCommitteeRepository committees; private final CommitteeMemberRepository committeeMembers; private final DefenseSessionRepository defenses; private final RegistrationPeriodRepository periods; private final LecturerRepository lecturers; private final UserRepository users; private final ProjectAssignmentRepository assignments; private final TopicSupervisorRepository supervisors; private final ScoreSheetRepository sheets; private final ScoreDetailRepository details; private final EvaluationAssignmentRepository evaluations; private final ResultVersionRepository results; private final GradeChangeRequestRepository changes; private final GroupMemberRepository groupMembers; private final NotificationService notifications; private final Clock clock;
 public EvaluationAdministrationService(EvaluationCommitteeRepository committees,CommitteeMemberRepository committeeMembers,DefenseSessionRepository defenses,RegistrationPeriodRepository periods,LecturerRepository lecturers,UserRepository users,ProjectAssignmentRepository assignments,TopicSupervisorRepository supervisors,ScoreSheetRepository sheets,ScoreDetailRepository details,EvaluationAssignmentRepository evaluations,ResultVersionRepository results,GradeChangeRequestRepository changes,GroupMemberRepository groupMembers,NotificationService notifications,Clock clock){this.committees=committees;this.committeeMembers=committeeMembers;this.defenses=defenses;this.periods=periods;this.lecturers=lecturers;this.users=users;this.assignments=assignments;this.supervisors=supervisors;this.sheets=sheets;this.details=details;this.evaluations=evaluations;this.results=results;this.changes=changes;this.groupMembers=groupMembers;this.notifications=notifications;this.clock=clock;}
 @Transactional @BusinessAudit(action="COMMITTEE_CREATE",entityType="EVALUATION_COMMITTEE") public Long createCommittee(CreateCommitteeRequest r,Long actor){manager(actor);RegistrationPeriod p=periods.findById(r.periodId()).orElseThrow(()->new ResourceNotFoundException("Registration period was not found."));EvaluationCommittee c=new EvaluationCommittee();c.setPeriod(p);c.setFaculty(p.getFaculty());c.setName(r.name().trim());c.setCreatedBy(user(actor));c.setCreatedAt(LocalDateTime.now(clock));return committees.save(c).getId();}
 @Transactional @BusinessAudit(action="COMMITTEE_MEMBER_ADD",entityType="EVALUATION_COMMITTEE",entityIdArgument=0) public void addMember(Long committeeId,AddCommitteeMemberRequest r,Long actor){manager(actor);EvaluationCommittee c=committee(committeeId);if(c.getStatus()!=CommitteeStatus.DRAFT)throw new BusinessRuleException("Only a draft committee can be changed.");if(committeeMembers.findByCommitteeId(committeeId).size()>=5)throw new BusinessRuleException("A committee has at most five members.");if(committeeMembers.findByCommitteeId(committeeId).stream().anyMatch(x->x.getSlotNo()==r.slotNo()||x.getLecturer().getId().equals(r.lecturerId())||x.getCommitteeRole()==r.role()&&r.role()!=CommitteeRole.MEMBER))throw new ConflictException("Duplicate committee slot, lecturer, or office.");CommitteeMember m=new CommitteeMember();m.setCommittee(c);m.setLecturer(lecturers.findById(r.lecturerId()).orElseThrow(()->new ResourceNotFoundException("Lecturer was not found.")));m.setSlotNo(r.slotNo());m.setCommitteeRole(r.role());committeeMembers.save(m);}
 @Transactional @BusinessAudit(action="DEFENSE_SCHEDULE",entityType="DEFENSE_SESSION") public Long schedule(CreateDefenseRequest r,Long actor){manager(actor);if(!r.startsAt().isBefore(r.endsAt()))throw new BusinessRuleException("Defense start time must be before end time.");ProjectAssignment a=assignment(r.assignmentId());EvaluationCommittee c=committee(r.committeeId());List<CommitteeMember> ms=committeeMembers.findByCommitteeId(c.getId());if(ms.size()<3||ms.size()>5||ms.stream().noneMatch(x->x.getCommitteeRole()==CommitteeRole.CHAIR)||ms.stream().noneMatch(x->x.getCommitteeRole()==CommitteeRole.SECRETARY))throw new BusinessRuleException("A committee needs 3-5 members, one chair and one secretary.");if(defenses.hasCommitteeConflict(c.getId(),r.startsAt(),r.endsAt()))throw new ConflictException("The committee already has a defense in this time range.");if(supervisors.findByTopicIdOrderBySlotNoAsc(a.getTopic().getId()).stream().anyMatch(s->ms.stream().anyMatch(m->m.getLecturer().getId().equals(s.getLecturer().getId()))))throw new BusinessRuleException("A topic supervisor cannot be on its defense committee.");DefenseSession d=new DefenseSession();d.setAssignment(a);d.setCommittee(c);d.setPeriod(a.getPeriod());d.setLocation(r.location().trim());d.setStartsAt(r.startsAt());d.setEndsAt(r.endsAt());return defenses.save(d).getId();}
 @Transactional @BusinessAudit(action="RESULT_FINALIZE",entityType="RESULT_VERSION",entityIdArgument=0) public ResultResponse finalizeResult(Long assignmentId,Long actor){manager(actor);ProjectAssignment a=assignment(assignmentId);if(results.findByAssignmentIdAndStatus(assignmentId,ResultStatus.PUBLISHED).isPresent())throw new BusinessRuleException("A published result cannot be finalized again.");List<EvaluationAssignment> es=evaluations.findAll().stream().filter(e->e.getAssignment().getId().equals(assignmentId)&&e.getStatus()==EvaluationStatus.ACTIVE).toList();if(es.isEmpty())throw new BusinessRuleException("This assignment has no evaluation assignments.");Map<Long,Long> submitted=es.stream().filter(e->sheets.findByEvaluationId(e.getId()).map(s->s.getStatus()==ScoreSheetStatus.SUBMITTED).orElse(false)).collect(java.util.stream.Collectors.groupingBy(e->e.getComponent().getId(),java.util.stream.Collectors.counting()));for(EvaluationAssignment e:es)if(submitted.getOrDefault(e.getComponent().getId(),0L)<e.getComponent().getExpectedEvaluators())throw new BusinessRuleException("Cannot finalize while a required score sheet is missing.");List<BigDecimal> values=es.stream().map(e->sheets.findByEvaluationId(e.getId()).orElseThrow()).map(s->details.findBySheetId(s.getId()).stream().map(ScoreDetail::getScore).reduce(BigDecimal.ZERO,BigDecimal::add)).toList();BigDecimal score=values.stream().reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(values.size()),2,RoundingMode.HALF_UP);ResultVersion v=new ResultVersion();v.setAssignment(a);v.setVersionNo((int)results.countByAssignmentId(assignmentId)+1);v.setFinalScore(score);v.setFinalizedBy(user(actor));v.setFinalizedAt(LocalDateTime.now(clock));es.forEach(e->sheets.findByEvaluationId(e.getId()).ifPresent(s->s.setStatus(ScoreSheetStatus.LOCKED)));v=results.save(v);return result(v);}
 @Transactional @BusinessAudit(action="RESULT_PUBLISH",entityType="RESULT_VERSION",entityIdArgument=0) public ResultResponse publish(Long resultId,Long actor){manager(actor);ResultVersion v=results.findById(resultId).orElseThrow(()->new ResourceNotFoundException("Result was not found."));if(v.getStatus()!=ResultStatus.FINALIZED)throw new BusinessRuleException("Only a finalized result can be published.");v.setStatus(ResultStatus.PUBLISHED);v.setPublishedBy(user(actor));v.setPublishedAt(LocalDateTime.now(clock));groupMembers.findByGroupIdAndLeftAtIsNullOrderBySlotNoAsc(v.getAssignment().getGroup().getId()).forEach(m->notifications.publish(m.getStudent().getUser().getId(),"result-published-"+v.getId(),"Kết quả đề tài","Kết quả đánh giá của nhóm đã được công bố.","/results/"+v.getId()));return result(v);}
 @Transactional public Long requestChange(Long sheetId,CreateGradeChangeRequest r,Long actor){ScoreSheet s=sheets.findById(sheetId).orElseThrow(()->new ResourceNotFoundException("Score sheet was not found."));if(!s.getEvaluation().getLecturer().getUser().getId().equals(actor))throw new AccessDeniedException("Only the evaluator can request a score change.");if(s.getStatus()!=ScoreSheetStatus.LOCKED||changes.existsBySheetIdAndStatusIn(sheetId,List.of(GradeChangeStatus.PENDING,GradeChangeStatus.APPROVED)))throw new BusinessRuleException("This score sheet cannot receive another change request.");GradeChangeRequest q=new GradeChangeRequest();q.setSheet(s);q.setRequestedBy(user(actor));q.setReason(r.reason().trim());q.setCreatedAt(LocalDateTime.now(clock));return changes.save(q).getId();}
 @Transactional public void reviewChange(Long id,ReviewGradeChangeRequest r,Long actor){manager(actor);GradeChangeRequest q=changes.findById(id).orElseThrow(()->new ResourceNotFoundException("Grade change request was not found."));if(q.getStatus()!=GradeChangeStatus.PENDING)throw new BusinessRuleException("Only a pending request may be reviewed.");q.setReviewedBy(user(actor));q.setReviewedAt(LocalDateTime.now(clock));q.setReviewComment(r.comment());if(Boolean.TRUE.equals(r.approved())){q.setStatus(GradeChangeStatus.APPLIED);q.setAppliedAt(LocalDateTime.now(clock));q.getSheet().setStatus(ScoreSheetStatus.DRAFT);}else q.setStatus(GradeChangeStatus.REJECTED);}
 private void manager(Long id){boolean ok=users.findWithRolesById(id).map(u->u.getUserRoles().stream().anyMatch(x->x.getRole().getCode()==RoleCode.ADMIN||x.getRole().getCode()==RoleCode.LECTURER)).orElse(false);if(!ok)throw new AccessDeniedException("Only lecturers or administrators can manage evaluation.");} private User user(Long id){return users.findById(id).orElseThrow(()->new ResourceNotFoundException("User was not found."));} private EvaluationCommittee committee(Long id){return committees.findById(id).orElseThrow(()->new ResourceNotFoundException("Committee was not found."));} private ProjectAssignment assignment(Long id){return assignments.findById(id).orElseThrow(()->new ResourceNotFoundException("Project assignment was not found."));} private ResultResponse result(ResultVersion v){return new ResultResponse(v.getId(),v.getAssignment().getId(),v.getVersionNo(),v.getFinalScore(),v.getStatus());}
}
